+      let stderr = "";
+      child.stderr.on("data", (bytes) => {
+        stderr += bytes;
+      });
+      exited = new Promise((done, reject) => {
+        child.once("error", reject);
+        child.once("exit", (code) => done(code));
+      });
+      await waitFor(() => existsSync(fixture.record));
